"""Fixed registry shared by the demo and explicit trusted local library seeding.

No project discovery, owner-media import, HTTP writes or user-selected paths.
"""
from pathlib import Path

from autoreels.local.asset_library import import_asset, list_assets
from .synthetic_image import IMAGE, IMAGE_NAME
from .synthetic_video import VIDEO, VIDEO_NAME
from .synthetic_soundtrack import TRACKS

VISUAL_ASSETS = ((3,IMAGE),(4,VIDEO))


def register_fixture_assets(root: Path, public_dir: Path):
    """Populate an isolated dedicated library from bundled generated bytes."""
    if not public_dir.is_absolute() or public_dir.resolve()!=public_dir or not public_dir.is_dir():
        raise ValueError("canonical bundled asset directory required")
    entries=((*((f"synthetic-soundtrack-{i}.wav",asset) for i,asset in enumerate(TRACKS,1)),
              (IMAGE_NAME,IMAGE),(VIDEO_NAME,VIDEO)))
    for filename,asset in entries:
        import_asset(root,public_dir/filename,asset)
    return list_assets(root)
